<script setup lang="ts">
import {ref,onMounted} from 'vue'
import {api,requestKey,setCsrf} from '../api/client'
import {useGuest} from '../stores/guest'
import {names,type Family} from '../types'
const guest=useGuest(),status=ref<{approved:boolean;provider_status:string;remaining_today:number;message:string}|null>(null),code=ref(''),error=ref(''),message=ref(''),busy=ref(false),deleteConfirm=ref(false)
async function run(fn:()=>Promise<void>){busy.value=true;error.value='';message.value='';try{await fn()}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
async function load(){status.value=await api('/ai/status')}
async function redeem(){await run(async()=>{const r=await api<{csrf_token:string}>('/ai/redeem','POST',{code:code.value});setCsrf(r.csrf_token);code.value='';await guest.refresh();await load();message.value='Invitation redeemed. Access is bound to this guest profile.'})}
async function download(){await run(async()=>{const data=await api('/export','POST');const url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='human-fluid-notebook.json';a.click();URL.revokeObjectURL(url);message.value='Notebook exported.'})}
async function restore(event:Event){const input=event.target as HTMLInputElement;const file=input.files?.[0];if(!file)return;await run(async()=>{if(file.size>20000000)throw new Error('Choose a notebook under 20 MB.');const body=JSON.parse(await file.text());if(body.schema_version!==1||!Array.isArray(body.history)||body.history.length>2000||Object.keys(body).some(k=>!['schema_version','history'].includes(k)))throw new Error('Choose a version 1 notebook with at most 2,000 records.');let restored=0;let batch:unknown[]=[];for(const entry of body.history){const next={schema_version:1,history:[...batch,entry]};if(JSON.stringify(next).length>700000&&batch.length){const result=await api<{restored:number}>('/restore','POST',{schema_version:1,history:batch},requestKey());restored+=result.restored;batch=[]}batch.push(entry)}if(batch.length){const result=await api<{restored:number}>('/restore','POST',{schema_version:1,history:batch},requestKey());restored+=result.restored}message.value=`${restored} records restored as unverified history. AI and admin access are never imported.`});input.value=''}
async function remove(){if(!deleteConfirm.value)return;await run(async()=>{await api('/me/data','DELETE',{confirm:true});Object.keys(localStorage).filter(k=>k.startsWith('hf-')).forEach(k=>localStorage.removeItem(k));location.assign('/')})}
async function changeLevel(family:Family,value:string){await run(async()=>{await api('/families/'+family+'/level','POST',{level:Number(value)});await guest.refresh();message.value='Practice level saved. Fixed assessments are unchanged.'})}
function clearDrafts(){Object.keys(localStorage).filter(k=>k.startsWith('hf-answer-')||k.startsWith('hf-draft-')).forEach(k=>localStorage.removeItem(k));message.value='Local unsent answer drafts cleared. Saved server scratchpads remain with their problems.'}
onMounted(()=>run(load))
</script>
<template><span class="eyebrow">YOUR NOTEBOOK / SETTINGS</span><h1>Keep your place.</h1><p class="lead">Manage your practice, your data, and optional discussion.</p><div v-if="error" class="error" role="alert">{{error}}</div><p v-if="message" class="notice" role="status">{{message}}</p><div class="settings-grid"><section class="panel"><span class="eyebrow">OPTIONAL / OWNER-APPROVED</span><h2>AI access</h2><template v-if="status"><p><strong>{{status.approved?'Approved for discussion':'Invitation required'}}</strong> · Provider {{status.provider_status}}</p><p>{{status.message}}</p><p v-if="status.approved">{{status.remaining_today}} request(s) remaining today. Provider availability is checked only when you explicitly send; configured does not mean a live connection has been verified.</p><p v-if="status.provider_status==='disabled'" class="notice">AI discussion is disabled. Every practice problem still includes a deterministic worked explanation.</p></template><form @submit.prevent="redeem"><label>Owner-issued invitation<input v-model="code" type="password" autocomplete="off" maxlength="100" placeholder="Paste your single-use code"></label><button :disabled="busy||!code" class="primary">Redeem invitation →</button></form></section><section class="panel"><span class="eyebrow">PRACTICE / MANUAL CONTROL</span><h2>Choose your starting level</h2><p>Four designed levels, not ability estimates. Manual changes are logged and do not change fixed checks.</p><label v-for="(name,id) in names" :key="id" class="level-control">{{name}}<select :value="guest.me?.levels[id]??1" :disabled="busy" @change="changeLevel(id,($event.target as HTMLSelectElement).value)"><option v-for="n in 4" :key="n" :value="n">Level {{n}}</option></select></label></section><section class="panel"><span class="eyebrow">PORTABLE / WITHOUT IDENTITY</span><h2>Your data</h2><p>Your guest cookie connects you to this server’s saved notebook. Clearing it loses automatic access. Exports contain owned history and notes, with no credentials or sealed solutions. Restored outcomes are marked unverified and excluded from canonical measurements.</p><div class="actions"><button @click="download" :disabled="busy">Export notebook ↓</button><label class="button file-button">Restore notebook ↑<input type="file" accept="application/json,.json" @change="restore" :disabled="busy"></label></div><button class="text-button" @click="clearDrafts">Clear local unsent answer drafts</button></section><section class="panel danger-panel"><span class="eyebrow">THIS GUEST PROFILE ONLY</span><h2>Delete your notebook</h2><p>Permanently remove this profile’s sessions, attempts, notes, discussions, and AI grants. Other visitors’ notebooks remain intact. Export first if you want a copy.</p><label class="checkbox"><input v-model="deleteConfirm" type="checkbox">I understand this deletes my saved data and access.</label><button class="danger" @click="remove" :disabled="busy||!deleteConfirm">Delete my data</button></section></div></template>
